/**
 * Модуль обробки звітності з навчальних курсів.
 * Автор: Оксана Петренко, IT-Академія Київ
 * Версія: 1.4.2
 */

const config = {
  minGradeForPass: 60,
  maxRetakes: 2,
  reportingFrequency: 'weekly',
  notifyEmail: 'reports@kyiv-it.edu.ua'
};

/**
 * Функція для згенерування щотижневого звіту.
 * @param {Array} studentRecords - Масив записів студентів.
 * @returns {Object} - Зібрані статистичні дані.
 */
function generateWeeklyReport(studentRecords) {
  let totalStudents = studentRecords.length;
  let passedCount = 0;
  let totalGrades = 0;

  // Перебираємо кожного студента для розрахунку середнього балу
  studentRecords.forEach(record => {
    if (record.finalGrade >= config.minGradeForPass) {
      passedCount++;
    }
    totalGrades += record.finalGrade;
  });

  const averageGrade = totalStudents > 0 ? (totalGrades / totalStudents).toFixed(2) : 0;
  const passRate = totalStudents > 0 ? ((passedCount / totalStudents) * 100).toFixed(1) : 0;

  return {
    reportDate: new Date().toISOString(),
    totalStudents: totalStudents,
    averageGrade: parseFloat(averageGrade),
    passRate: parseFloat(passRate) + '%'
  };
}

// Приклад використання в консолі під час тестування
const mockData = [
  { name: 'Іван Іваненко', finalGrade: 85 },
  { name: 'Марія Сидоренко', finalGrade: 72 },
  { name: 'Олег Тарасенко', finalGrade: 55 }
];

console.log(generateWeeklyReport(mockData));

/**
 * Додаткова функція для експорту даних у CSV формат.
 * Використовується для передачі даних до зовнішньої бухгалтерії.
 */
function exportToCSV(records) {
  const headers = ['Name', 'Grade', 'Status'];
  const rows = records.map(r => [
    r.name,
    r.finalGrade,
    r.finalGrade >= config.minGradeForPass ? 'PASS' : 'FAIL'
  ]);

  return [headers, ...rows].map(row => row.join(',')).join('\n');
}
