// نویسنده: علی رضایی
// تاریخ: ۱۴۰۳/۰۲/۱۵

import { WebSocket } from 'ws';
import { logger } from '../utils/logger';

/**
 * کلاس مدیریت سفارهای که توسط تیکر (Taker) ارسال می‌شود.
 * این ماژول مسئول اتصال به سرور ریو (Rio) و پردازش سیگنال‌های خرید/فروش است.
 */
class TakerOrderExecutor {
  private ws: WebSocket;
  private apiKey: string;
  private maxOrderSize: number = 50000000; // 0.5 BTC

  constructor(apiKey: string, serverUrl: string) {
    this.apiKey = apiKey;
    this.ws = new WebSocket(serverUrl);
    this.initialize();
  }

  private initialize() {
    this.ws.on('open', () => {
      logger.info('اتصال به سرور ریو برقرار شد.');
      this.sendHeartbeat();
    });

    this.ws.on('message', (data) => {
      const message = JSON.parse(data.toString());
      if (message.type === 'order_signal') {
        this.handleSignal(message);
      }
    });

    this.ws.on('error', (error) => {
      logger.error('خطا در اتصال WebSocket:', error);
    });
  }

  private sendHeartbeat() {
    const payload = {
      type: 'heartbeat',
      timestamp: Date.now(),
      agent_id: 'TAKER-01'
    };
    this.ws.send(JSON.stringify(payload));
  }

  private handleSignal(signal: any) {
    const { action, amount, price } = signal;

    // بررسی اعتباریت مبلغ سفارش
    if (amount > this.maxOrderSize) {
      logger.warn(`مبلغ سفارش ${amount} بیش از حد مجاز (${this.maxOrderSize}) است. سفارش رد شد.`);
      return;
    }

    logger.info(`دریافت سیگنال ${action} با مبلغ ${amount} USDT و قیمت ${price} BTC`);

    // ارسال سفارش به صرافی
    this.executeOrder(action, amount, price);
  }

  private async executeOrder(action: string, amount: number, price: number) {
    try {
      // شبیه‌سازی درخواست API
      logger.info(`در حال ارسال سفارش ${action}...`);
      // در نسخه واقعی، اینجاست که از axios برای فراخوانی API صرافی استفاده می‌کنیم
      await new Promise(resolve => setTimeout(resolve, 50)); 
      logger.success('سفارش با موفقیت ثبت شد.');
    } catch (error) {
      logger.error('شکست در ثبت سفارش:', error);
    }
  }
}

export default TakerOrderExecutor;
