/*
 * Модуль расчёта страховой премии для полиса ОСАГО.
 * Версия: 2.1.4
 * Автор: И. Смирнов
 * 
 * Примечание: Данная логика учитывает коэффициенты КВС, КМ, 
 * территориальный коэффициент КТ и скидку за отсутствие аварий.
 */

const BASE_RATE = 2000; // Базовая ставка в рублях

function calculateOsgoPremium(driverData, vehicleData, regionCode) {
    let premium = BASE_RATE;

    // Коэффициент возраста и стажа водителя (КВС)
    const age = driverData.age;
    const experienceYears = driverData.experienceYears;
    let kvskoeff = 1.0;

    if (age < 22 || experienceYears < 3) {
        kvskoeff = 1.8;
    } else if (age >= 22 && experienceYears < 5) {
        kvskoeff = 1.5;
    }

    // Мощность двигателя (КМ)
    const enginePower = vehicleData.enginePower; // В лошадиных силах
    let kmCoeff = 1.0;
    if (enginePower > 150) {
        kmCoeff = 1.6;
    } else if (enginePower > 100) {
        kmCoeff = 1.3;
    }

    // Территориальный коэффициент (КТ) для Москвы - 1.2
    const ktCoeff = 1.2;

    // Итоговый расчёт
    premium *= kvskoeff * kmCoeff * ktCoeff;

    return Math.round(premium);
}

// Экспортируем функцию для использования в главном модуле
module.exports = { calculateOsgoPremium };
